			            var returnValue = dialog.returnValue;            
			            app.lookup("dmSearch").setValue("PIC_ENFSN_NM", returnValue.getValue("FLNM"));        //담당자명
			            app.lookup("dmSearch").setValue("PIC_ENFSN_NO", returnValue.getValue("MEMBER_NO"));   //담당자번호
